3. Implement the event horizon and luminous disk
Start with this scene component. It gives you a real dark sphere, a shader-rendered disk, and a particle layer that can be upgraded independently.
BlackHoleScene.tsx
import { Canvas } from "@react-three/fiber";
import {
Bloom,
EffectComposer,
Vignette,
} from "@react-three/postprocessing";
import { AccretionDisk } from "./AccretionDisk";
import { DiskParticles } from "./DiskParticles";
import { GravitationalLensing } from "../effects/GravitationalLensing";
function BlackHole() {
return (
<>
{/* Accretion disk behind the event horizon */}

<AccretionDisk />
{/* Existing particle simulation, replaced with GPU motion */}
<DiskParticles count={40000} />
{/* The black silhouette */}
<mesh renderOrder={5}>

<sphereGeometry args={[0.72, 96, 96]} />
<meshBasicMaterial color="#000000" />

</mesh>
{/* A restrained luminous ring */}
<mesh rotation={[Math.PI / 2, 0, 0]} renderOrder={6}>
<torusGeometry args={[0.76, 0.018, 12, 256]} />
<meshBasicMaterial

color="#fff1c7"
toneMapped={false}
/>
</mesh>
</>
);
}
export default function BlackHoleScene() {
return (
<Canvas
camera={{

position: [0, 2.4, 8],
fov: 38,
near: 0.1,
far: 100,
}}
dpr={[1, 1.5]}
gl={{ antialias: true }}
>
<color attach="background" args={["#010208"]} />
<BlackHole />
<EffectComposer multisampling={0}>
<GravitationalLensing
center={[0.5, 0.5]}

radius={0.23}

strength={0.012}
/>
<Bloom
intensity={1.15}
luminanceThreshold={0.65}
luminanceSmoothing={0.25}
mipmapBlur
/>
<Vignette
offset={0.2}
darkness={0.7}
/>
</EffectComposer>
</Canvas>
);
}
These are initial artistic settings, not universal optimal values. In particular, the disk orientation and camera position determine whether the ring lines up with the silhouette. The example is a starting composition, not a finished physically accurate black-hole renderer.
Important: the torus above is a stylized ring, not a true relativistic photon ring. Also, a black sphere alone does not simulate an event horizon; it supplies the visual silhouette.
AccretionDisk.tsx
Render a continuous emissive disk underneath the particles. The following shader uses a plane with radial falloff, procedural bands, and animated turbulence.
import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
const vertexShader = `
varying vec2 vUv;
void main() {
vUv = uv;

gl_Position =
projectionMatrix *

modelViewMatrix *
vec4(position, 1.0);
}
`;
const fragmentShader = `
uniform float uTime;
varying vec2 vUv;
void main() {

vec2 p = (vUv - 0.5) * 4.0;
float r = length(p);
float a = atan(p.y, p.x);

// Annular disk: no material inside the inner edge.
float inner = smoothstep(0.62, 0.76, r);
float outer = 1.0 - smoothstep(1.72, 2.0, r);
// Several scales of procedural turbulence.

float swirl =
sin(a * 12.0 - r * 18.0 + uTime * 0.8);
float bands =

sin(r * 42.0 - a * 3.0 - uTime * 1.2);
float noise =
0.65 + 0.2 * swirl + 0.15 * bands;
// Brightness concentrates toward the inner disk.
float heat = 1.0 - smoothstep(0.7, 1.85, r);

float intensity =
inner * outer * max(noise, 0.0) *

(0.25 + 2.5 * heat);
vec3 blue = vec3(0.025, 0.18, 0.65);
vec3 cyan = vec3(0.12, 0.75, 1.0);
vec3 gold = vec3(1.0, 0.32, 0.055);
vec3 white = vec3(1.0, 0.88, 0.62);

vec3 color = mix(blue, cyan, heat * 0.5);
color = mix(color, gold, pow(heat, 2.0));
color = mix(color, white, pow(heat, 8.0));
gl_FragColor = vec4(color * intensity, intensity);

}
`;
export function AccretionDisk() {

const material = useRef<THREE.ShaderMaterial>(null);
useFrame(({ clock }) => {
if (material.current) {

material.current.uniforms.uTime.value =
clock.elapsedTime;

}
});
return (
<mesh
rotation={[1.12, 0, 0]}
renderOrder={1}

>
<planeGeometry args={[4.4, 4.4, 1, 1]} />
<shaderMaterial
ref={material}
vertexShader={vertexShader}
fragmentShader={fragmentShader}
uniforms={{
uTime: { value: 0 },
}}
transparent
depthWrite={false}
side={THREE.DoubleSide}
blending={THREE.AdditiveBlending}
toneMapped={false}
/>
</mesh>
);
}
This shader is deliberately stylized. It creates a luminous disk, not a physically computed plasma temperature map. Its smooth radial mask, procedural bands, and additive blending should give you a stronger visual foundation than a uniform cloud of dots.
One tuning note: r is measured in shader-plane coordinates. The disk dimensions, inner/outer thresholds, sphere radius, and ring radius are related but not identical units. Adjust them together when you change the geometry.
4. Upgrade the particles to GPU-driven orbital motion
This is the part that directly upgrades your existing simulation.
Instead of updating 40,000 particle positions on the CPU every frame, store each particle's radius, starting angle, and size once. Calculate its position in the vertex shader using elapsed time.
DiskParticles.tsx
import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
const vertexShader = `
attribute float aRadius;
attribute float aAngle;
attribute float aSize;

attribute vec3 aColor;
uniform float uTime;
varying vec3 vColor;
varying float vAlpha;
void main() {

float angularSpeed =

0.42 * pow(aRadius, -1.5);
float angle =

aAngle + uTime * angularSpeed;
vec3 p = vec3(
cos(angle) * aRadius,

sin(angle) * aRadius,
0.0

);
vec4 mvPosition =
modelViewMatrix * vec4(p, 1.0);
gl_Position =
projectionMatrix * mvPosition;

gl_PointSize = clamp(
aSize * (260.0 / max(-mvPosition.z, 0.1)),

1.0,
7.0

);
vColor = aColor;
vAlpha = 0.72;
}
`;

const fragmentShader = `
varying vec3 vColor;
varying float vAlpha;
void main() {

vec2 p = gl_PointCoord - 0.5;
float d = length(p);
float alpha =

1.0 - smoothstep(0.05, 0.5, d);
if (alpha < 0.01) discard;
gl_FragColor = vec4(

vColor * 1.35,
alpha * vAlpha

);

}
`;
export function DiskParticles({
count = 40000,
}: {
count?: number;

}) {
const material = useRef<THREE.ShaderMaterial>(null);
const attributes = useMemo(() => {
const radius = new Float32Array(count);
const angle = new Float32Array(count);
const size = new Float32Array(count);

const color = new Float32Array(count * 3);
const inner = 0.82;
const outer = 1.95;
for (let i = 0; i < count; i++) {
// Uniform sampling over disk area.

const u = Math.random();
radius[i] = Math.sqrt(

inner * inner +
u * (outer * outer - inner * inner)
);

angle[i] = Math.random() * Math.PI * 2;
size[i] = 1.0 + Math.random() * 2.2;
const t =
(radius[i] - inner) / (outer - inner);

// Hotter inner disk, cooler outer disk.
color[i * 3] = THREE.MathUtils.lerp(1.0, 0.08, t);

color[i * 3 + 1] = THREE.MathUtils.lerp(0.65, 0.42, t);
color[i * 3 + 2] = THREE.MathUtils.lerp(0.24, 1.0, t);

}
return { radius, angle, size, color };
}, [count]);
useFrame(({ clock }) => {
if (material.current) {

material.current.uniforms.uTime.value =
clock.elapsedTime;

}
});
return (
<points rotation={[1.12, 0, 0]} renderOrder={2}>
<bufferGeometry>
<bufferAttribute

attach="attributes-aRadius"
args={[attributes.radius, 1]}
/>
<bufferAttribute
attach="attributes-aAngle"
args={[attributes.angle, 1]}
/>
<bufferAttribute
attach="attributes-aSize"
args={[attributes.size, 1]}
/>
<bufferAttribute
attach="attributes-aColor"
args={[attributes.color, 3]}
/>
</bufferGeometry>
<shaderMaterial
ref={material}
vertexShader={vertexShader}
fragmentShader={fragmentShader}

uniforms={{ uTime: { value: 0 } }}
transparent
depthWrite={false}
blending={THREE.AdditiveBlending}
toneMapped={false}
/>
</points>
);
}
Why this is better
The particle positions are calculated on the GPU, reducing per-frame JavaScript work.
Inner particles orbit faster than outer particles.
The particle distribution has a defined inner and outer radius.
Colors vary smoothly from hot inner material to cooler outer material.
Soft circular point sprites integrate more naturally with the continuous disk.
This still uses a simplified orbital model. It does not calculate relativistic trajectories, and it assumes a thin, flat disk. For a more realistic model, you'll eventually want to account for relativistic orbital behavior and the apparent bending of light.
One detail to keep consistent: use the same disk rotation for the particle layer, continuous disk, and any ring that is meant to align with the disk. In the scene code above, set the ring's rotation to [1.12, 0, 0] rather than Math.PI / 2.
5. Add a gravitational-lensing post-processing effect
A screen-space shader is a good first approximation. It bends the rendered image around the black hole's projected center, giving you an immediate sense of warped space.
Create effects/GravitationalLensing.tsx:
import {
createEffectComponent,
} from "@react-three/postprocessing";
import { Effect } from "postprocessing";
import {
Uniform,
Vector2,
} from "three";
const fragmentShader = `
uniform vec2 center;
uniform float radius;
uniform float strength;

void mainUv(inout vec2 uv) {
// Correct for the screen aspect ratio.
vec2 p = vec2(
(uv.x - center.x) * resolution.x / resolution.y,

uv.y - center.y
);
float r = length(p);
// Limit the effect to the area around the hole.
float falloff =
1.0 - smoothstep(0.0, radius, r);

// Artistic radial lensing approximation.

float bend =
strength * falloff / max(r, 0.08);
p += normalize(p) * bend;

uv = center + vec2(
p.x * resolution.y / resolution.x,
p.y

);

}
`;
class LensingEffect extends Effect {
constructor({
center = [0.5, 0.5],
radius = 0.23,

strength = 0.002,
}: {
center?: [number, number];
radius?: number;
strength?: number;
} = {}) {
super("GravitationalLensing", fragmentShader, {
uniforms: new Map([
["center", new Uniform(new Vector2(...center))],
["radius", new Uniform(radius)],
["strength", new Uniform(strength)],
]),
});
}
}
export const GravitationalLensing =
createEffectComponent(LensingEffect);
This follows the custom-effect pattern supported by React Postprocessing: define an Effect, expose its uniforms, and wrap it as a React component.
